-- Generated from content/questions.json; SHA-256 cecf5b4bc87b33ad26ff57440c301c1a37d987b30ed0ae4c001b3f8c18bfb840.
-- Existing online-game options remain unchanged; practice grading has its own complete catalog.
on conflict(question_id) do update set
  canonical_question_id=excluded.canonical_question_id,chapter=excluded.chapter,question_type=excluded.question_type,
  live_enabled=current.live_enabled and (current.catalog_version is null or (current.practice_options=excluded.practice_options and current.practice_correct_options=excluded.practice_correct_options)),
  arena_enabled=current.arena_enabled and (current.catalog_version is null or (current.practice_options=excluded.practice_options and current.practice_correct_options=excluded.practice_correct_options)),
  answerable=excluded.answerable,practice_options=excluded.practice_options,practice_correct_options=excluded.practice_correct_options,
  catalog_version=excluded.catalog_version;
-- Retire removed questions without deleting versions referenced by attempts or games.
update quiz_pk_private.questions set answerable=false,live_enabled=false,arena_enabled=false
where catalog_version is distinct from 'cecf5b4bc87b33ad26ff57440c301c1a37d987b30ed0ae4c001b3f8c18bfb840';
  select catalog_version,question_id,canonical_question_id,chapter,question_type,answerable,practice_options,practice_correct_options
  from quiz_pk_private.questions where catalog_version='cecf5b4bc87b33ad26ff57440c301c1a37d987b30ed0ae4c001b3f8c18bfb840'
  on conflict(catalog_version,question_id) do nothing;
